preConditionHook:
// A tie bar (close == open, within EL tolerance) fails BOTH sides,
// mirroring the EL twin's close-at-or-under-open / close-at-or-over-open
// failure tests.
ConditionOne = true;
ConditionTwo = true;
for (ii = 0; ii < (int)consecutiveBars; ++ii) {
    if (el_le(close[ii], open[ii])) ConditionOne = false;
    if (el_ge(close[ii], open[ii])) ConditionTwo = false;
}
